P['ku'] = dict(
 faq_title='Pirsên pir tên pirsîn', priv_title='Nepenîtî', open='Whenly veke', faq='Pirs', privacy='Nepenîtî',
 q=['Whenly belaş e?','Hesab pêwîst e?','Li ser telefona min dixebite?','Whenly kîjan zimanan piştgirî dike?','Ji Doodle çi cuda ye?','Ez dikarim ji bo kesekî din dagirim?','Kî dikare anketa min bibîne?','Bi daneyên min çi dibe?'],
 a=['Erê. Whenly bi tevahî belaş e û wê belaş bimîne. Ne dîwarê pereyan, ne reklam.',
    'Na. Kes hewceyî hesabekê nîne, ne jî yê ku anketê çêdike. Tu navê xwe dinivîsî û rojên xwe nîşan dikî.',
    'Erê. Whenly di her gerokê de dixebite û wek sepanekê li ekrana destpêkê tê zêdekirin, bê dikana sepanan.',
    'Bîst û sê, di nav wan de Kurdî, Îngilîzî, Fransî, Erebî, Hindî, Çînî, Rûsî, Tamazîxt û Şona. Ziman li gorî geroka te ye û bi bişkoka cîhanê tê guhertin.',
    'Whenly ji kesî tomarkirin naxwaze, reklaman nîşan nade û belaş e. Tu rojan li ser salnameyê nîşan dikî, û ronahiyeke trafîkê nîşan dide kengî her kes dikare.',
    'Erê. "Beşdarekî zêde bike" hilbijêre, navekî binivîse û rojan ji bo wî kesî nîşan bike.',
    'Her kesê ku lînk pê re ye. Lînk kodeke dirêj û tesadufî ye ku nayê texmînkirin, û rûpelên anketan ji aliyê motorên lêgerînê ve nayên tomarkirin. Lînkê tenê bi koma xwe re parve bike.',
    'Tenê sernav, nav û rojên nîşankirî tên tomarkirin, tiştekî din na. Ne e-name, ne hejmara telefonê, ne şopandin. Kontrol di destê te de ye: her kesê bi lînkê dikare anketê bi tevahî jê bibe, û wê demê her tişt ji bo her dem winda dibe. Heke kes jê nebe, piştî çalakiya dawî 12 mehan dimîne da ku tu vegerî, paşê bixweber tê jêbirin.'],
 h=['Whenly çi tomar dike','Whenly çi nake','Kî dikare anketekê bibîne','Çiqas dirêj, û kî biryar dide','Li ku, û pirs'],
 p=['Tenê tiştên ku tu bi xwe dinivîsî: sernavê anketê, navên beşdaran, rojên nîşankirî û demeke bijartî. Tiştekî din na. Ne e-name, ne hejmara telefonê, ne hesab, ne şîfre.',
    'Ne şopandin, ne reklam, ne cookieyên aliyê sêyem, ne analîtîk. Geroka te tenê zimanê te, navê te û anketên ku te vekirine bi awayekî herêmî bi bîr tîne, da ku tu tiştekî dîsa nenivîsî. Ew li ser amûra te dimîne.',
    'Her kesê ku lînk pê re ye. Lînk kodeke dirêj û tesadufî ye ku nayê texmînkirin, û rûpelên anketan ji aliyê motorên lêgerînê ve nayên tomarkirin; lînkê tenê bi koma xwe re parve bike. Her kesê bi lînkê dikare navan û rojan biguherîne an jê bibe; dema kesek navekî jê dibe, nîşeyeke kurt 30 rojan xuya dimîne da ku kom bizane ku ew ne xeletiya sepanê bû.',
    'Tu. Li kêleka sernavê "Vê anketê bi tevahî jê bibe" heye. Bitikîne (û piştrast bike), sernav, hemû nav û hemû rojên nîşankirî tavilê û ji bo her dem winda dibin, ji bo her kesî. Heke kes jê nebe, anket piştî çalakiya dawî 12 mehan dimîne da ku tu vegerî. Ev ne ji bo berhevkirina daneyan e; paşê bixweber tê jêbirin. Navekî jêbirî piştî 30 rojan ji bo her dem winda dibe.',
    'Dane li ser serverên Cloudflare tên tomarkirin. Whenly çavkaniya vekirî ye; kod û pirs li ser GITHUB in.'])

